function stableSort<T>(array: readonly T[], comparator: (a: T, b: T) => number) {
  const stabilized = array.map((el, index) => [el, index] as const);
  stabilized.sort((a, b) => {
    const order = comparator(a[0], b[0]);
    if (order !== 0) return order;
    return a[1] - b[1];
  });
  return stabilized.map((el) => el[0]);
}

function getComparator<Key extends keyof GrievanceRow>(order: Order, orderBy: Key) {
  return (a: GrievanceRow, b: GrievanceRow) => {
    const av = a[orderBy];
    const bv = b[orderBy];
    const aStr = Array.isArray(av) ? av.join(" ") : String(av).toLowerCase();
    const bStr = Array.isArray(bv) ? bv.join(" ") : String(bv).toLowerCase();
    if (aStr < bStr) return order === "asc" ? -1 : 1;
    if (aStr > bStr) return order === "asc" ? 1 : -1;
    return 0;
  };
}

const unique = <T,>(arr: T[]) => Array.from(new Set(arr));

/** Normalize text for robust search: remove diacritics/quotes/punct, lowercase, collapse spaces */
const normalizeText = (s: string) =>
  s
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "") // diacritics
    .replace(/[“”‘’"']/g, "") // curly/straight quotes
    .replace(/[^a-z0-9]+/g, " ") // non-alphanum to space
    .trim();

export default function ResponsiveGrievanceTable() {
  const [query, setQuery] = React.useState("");
  const [order, setOrder] = React.useState<Order>("asc");
  const [orderBy, setOrderBy] = React.useState<keyof GrievanceRow>("category");
  const [page, setPage] = React.useState(0);
  const [rowsPerPage, setRowsPerPage] = React.useState(10);
  const [expanded, setExpanded] = React.useState<Record<number, boolean>>({});
  const [categories, setCategories] = React.useState<string[]>([]);
  const [severities, setSeverities] = React.useState<Severity[]>([]);

  const allCategories = React.useMemo(() => unique(ALL_ROWS.map((r) => r.category)).sort(), []);
  const allSeverities: Severity[] = ["High", "Medium", "Low"];

  const handleSort = (property: keyof GrievanceRow) => {
    const isAsc = orderBy === property && order === "asc";
    setOrder(isAsc ? "desc" : "asc");
    setOrderBy(property);
  };

  const handleChangePage = (_: unknown, newPage: number) => setPage(newPage);
  const handleChangeRowsPerPage = (e: React.ChangeEvent<HTMLInputElement>) => {
    setRowsPerPage(parseInt(e.target.value, 10));
    setPage(0);
  };

  // Debounce search input for smoother typing
  const [pendingQ, setPendingQ] = React.useState("");
  React.useEffect(() => {
    const t = setTimeout(() => setQuery(pendingQ), 120);
    return () => clearTimeout(t);
  }, [pendingQ]);

  const filtered = React.useMemo(() => {
    const q = normalizeText(query);
    const tokens = q ? q.split(/\s+/).filter(Boolean) : [];

    return ALL_ROWS.filter((r) => {
      const categoryOk = categories.length ? categories.includes(r.category) : true;
      const severityOk = severities.length ? severities.includes(r.severity) : true;

      if (!categoryOk || !severityOk) return false;

      if (!tokens.length) return true;

      const hayNorm = normalizeText(
        [r.category, r.issue, r.severity, r.expectedResolutionTime, r.steps.join(" ")].join(" ")
      );

      // All tokens must exist (AND)
      return tokens.every((t) => hayNorm.includes(t));
    });
  }, [query, categories, severities]);

  const sorted = React.useMemo(
    () => stableSort(filtered, getComparator(order, orderBy)),
    [filtered, order, orderBy]
  );

  const paged = React.useMemo(
    () => sorted.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage),
    [sorted, page, rowsPerPage]
  );

  const toggleExpand = (idx: number) => setExpanded((prev) => ({ ...prev, [idx]: !prev[idx] }));
  const clearFilters = () => {
    setPendingQ("");
    setQuery("");
    setCategories([]);
    setSeverities([]);
    setPage(0);
  };

  const downloadCSV = () => {
    const headers = [
      "Category",
      "Issue",
      "Severity",
      "Expected Resolution Time",
      "Grievance Management Steps",
    ];
    const rows = sorted.map((r) => [
      r.category,
      r.issue.replaceAll('"', '""'),
      r.severity,
      r.expectedResolutionTime,
      r.steps.join(" | ").replaceAll('"', '""'),
    ]);
    const csv = [headers, ...rows].map((cols) => cols.map((c) => `"${String(c)}"`).join(",")).join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "grievances.csv";
    a.click();
    URL.revokeObjectURL(url);
  };

  // Compact menu styling for Selects
  const selectMenuProps = {
    PaperProps: {
      sx: {
        "& .MuiMenuItem-root": {
          minHeight: COMPACT_MENU_ITEM_H,
          fontSize: 12,
          py: 0.25,
        },
      },
    },
  };

  return (
    <Paper elevation={2} sx={{ p: 1.5, width: "100%", overflow: "hidden" }}>
      <Stack
        direction={{ xs: "column", sm: "row" }}
        spacing={1}
        alignItems={{ xs: "stretch", sm: "center" }}
        justifyContent="space-between"
        sx={{ mb: 1 }}
      >
        {/* <Typography variant="subtitle1" fontWeight={600}>
          Grievance Help Fil
        </Typography> */}

        <Stack
          direction={{ xs: "column", md: "row" }}
          spacing={1}
          alignItems={{ xs: "stretch", md: "center" }}
          flex={1}
        >
          <SearchField
            size="small"
            fullWidth
            placeholder="Search (category, issue, steps, etc.)"
            value={pendingQ}
            onChange={(e) => {
              setPendingQ(e.target.value);
              setPage(0);
            }}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon fontSize="small" />
                </InputAdornment>
              ),
              endAdornment: pendingQ ? (
                <InputAdornment position="end">
                  <CompactIconButton aria-label="clear" onClick={() => setPendingQ("")} edge="end" size="small">
                    <ClearIcon fontSize="small" />
                  </CompactIconButton>
                </InputAdornment>
              ) : undefined,
            }}
          />

          <CompactFormControl size="small">
            <InputLabel id="cat-label">Category</InputLabel>
            <Select
              labelId="cat-label"
              multiple
              value={categories}
              onChange={(e: SelectChangeEvent<string[]>) =>
                setCategories(
                  Array.isArray(e.target.value)
                    ? (e.target.value as string[])
                    : (String(e.target.value).split(",") as string[])
                )
              }
              input={<OutlinedInput label="Category" />}
              renderValue={(selected) => (
                <Stack direction="row" spacing={0.5} flexWrap="wrap">
                  {(selected as string[]).map((v) => (
                    <Chip key={v} label={v} size="small" />
                  ))}
                </Stack>
              )}
              MenuProps={selectMenuProps}
              sx={{
                "& .MuiSelect-select": { display: "flex", alignItems: "center" },
              }}
            >
              {allCategories.map((c) => (
                <MenuItem key={c} value={c}>
                  {c}
                </MenuItem>
              ))}
            </Select>
          </CompactFormControl>

          <CompactFormControl size="small">
            <InputLabel id="sev-label">Severity</InputLabel>
            <Select
              labelId="sev-label"
              multiple
              value={severities}
              onChange={(e: SelectChangeEvent<string[] | Severity[]>) => {
                const val = e.target.value;
                setSeverities(
                  Array.isArray(val)
                    ? (val as Severity[])
                    : (String(val).split(",") as Severity[])
                );
              }}
              input={<OutlinedInput label="Severity" />}
              renderValue={(selected) => (
                <Stack direction="row" spacing={0.5} flexWrap="wrap">
                  {(selected as Severity[]).map((s) => (
                    <Chip key={s} label={s} color={severityColor[s]} size="small" />
                  ))}
                </Stack>
              )}
              MenuProps={selectMenuProps}
            >
              {allSeverities.map((s) => (
                <MenuItem key={s} value={s}>
                  <Chip label={s} color={severityColor[s]} size="small" />
                </MenuItem>
              ))}
            </Select>
          </CompactFormControl>

          <Stack direction="row" spacing={0.5} justifyContent="flex-end">
            <Tooltip title="Export CSV of current view">
              <span>
                <CompactButton variant="outlined" startIcon={<DownloadIcon fontSize="small" />} onClick={downloadCSV}>
                  Export
                </CompactButton>
              </span>
            </Tooltip>
            <CompactButton variant="text" onClick={clearFilters}>
              Reset
            </CompactButton>
          </Stack>
        </Stack>
      </Stack>

      <TableContainer sx={{ maxHeight: 520 }}>
        <Table stickyHeader size="small">
          <TableHead>
            <TableRow>
              {COLUMNS.map((col) => (
                <TableCell key={col.id} sx={{ py: 0.5 }}>
                  <TableSortLabel
                    active={orderBy === (col.id as keyof GrievanceRow)}
                    direction={orderBy === (col.id as keyof GrievanceRow) ? order : "asc"}
                    onClick={() => handleSort(col.id as keyof GrievanceRow)}
                    hideSortIcon={col.id === "steps"}
                    disabled={col.id === "steps"}
                  >
                    <Typography variant="caption" sx={{ fontWeight: 600 }}>
                      {col.label}
                    </Typography>
                  </TableSortLabel>
                </TableCell>
              ))}
              <TableCell width={48} align="center" sx={{ py: 0.5 }} />
            </TableRow>
          </TableHead>

          <TableBody>
            {paged.map((row, idx) => {
              const absoluteIdx = page * rowsPerPage + idx;
              const isOpen = !!expanded[absoluteIdx];
              return (
                <React.Fragment key={`${row.category}-${absoluteIdx}`}>
                  <TableRow hover>
                    <TableCell sx={{ py: 0.5 }}>
                      <Chip label={row.category} size="small" />
                    </TableCell>
                    <TableCell sx={{ minWidth: 260, py: 0.5 }}>
                      <Typography variant="body2" sx={{ fontSize: 12, lineHeight: 1.2 }}>
                        {row.issue}
                      </Typography>
                    </TableCell>
                    <TableCell sx={{ py: 0.5 }}>
                      <Chip label={row.severity} color={severityColor[row.severity]} size="small" />
                    </TableCell>
                    <TableCell sx={{ py: 0.5 }}>
                      <Typography variant="body2" sx={{ fontSize: 12 }}>
                        {row.expectedResolutionTime}
                      </Typography>
                    </TableCell>
                    <TableCell
                      sx={{
                        maxWidth: 280,
                        whiteSpace: "nowrap",
                        overflow: "hidden",
                        textOverflow: "ellipsis",
                        py: 0.5,
                      }}
                    >
                      <Typography variant="body2" sx={{ fontSize: 12 }}>
                        {row.steps[0]}
                        {row.steps.length > 1 ? " …" : ""}
                      </Typography>
                    </TableCell>
                    <TableCell align="center" sx={{ py: 0.5 }}>
                      <CompactIconButton onClick={() => toggleExpand(absoluteIdx)} aria-label="expand row" size="small">
                        {isOpen ? <ExpandLessIcon fontSize="small" /> : <ExpandMoreIcon fontSize="small" />}
                      </CompactIconButton>
                    </TableCell>
                  </TableRow>

                  <TableRow>
                    <TableCell colSpan={6} sx={{ p: 0, borderBottom: 0 }}>
                      <Collapse in={isOpen} timeout="auto" unmountOnExit>
                        <Box sx={{ p: 1.5, bgcolor: (t) => alpha(t.palette.primary.main, 0.05) }}>
                          <Typography variant="caption" gutterBottom sx={{ fontWeight: 600 }}>
                            Grievance Management Steps
                          </Typography>
                          <ol style={{ margin: 0, paddingInlineStart: 18 }}>
                            {row.steps.map((s, i) => (
                              <li key={i} style={{ marginBottom: 2 }}>
                                <Typography variant="body2" sx={{ fontSize: 12 }}>
                                  {s}
                                </Typography>
                              </li>
                            ))}
                          </ol>
                        </Box>
                      </Collapse>
                    </TableCell>
                  </TableRow>
                </React.Fragment>
              );
            })}
            {paged.length === 0 && (
              <TableRow>
                <TableCell colSpan={7} align="center">
                  <Typography variant="body2" color="text.secondary" sx={{ py: 3, fontSize: 12 }}>
                    No results. Try adjusting your search or filters.
                  </Typography>
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </TableContainer>

      <TablePagination
        component="div"
        count={sorted.length}
        page={page}
        onPageChange={handleChangePage}
        rowsPerPage={rowsPerPage}
        onRowsPerPageChange={handleChangeRowsPerPage}
        rowsPerPageOptions={[5, 10, 20, 50]}
        sx={{
          "& .MuiTablePagination-toolbar": { minHeight: 36, py: 0.5 },
          "& .MuiTablePagination-selectLabel, & .MuiTablePagination-displayedRows": { fontSize: 12 },
          "& .MuiTablePagination-select": { fontSize: 12, height: COMPACT_INPUT_HEIGHT },
          "& .MuiInputBase-root": { height: COMPACT_INPUT_HEIGHT },
        }}
      />
    </Paper>
  );
}